CREATE OR REPLACE FUNCTION trip_private.a2e_group_join_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.trip_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.trips t WHERE t.id=NEW.trip_id AND t.a2e_room AND t.vibe='party') AND coalesce(trip_private.age_of(NEW.user_id),0)<21 THEN RAISE EXCEPTION 'This Party room is for 21+ only'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION trip_private.a2e_group_join_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION trip_private.a2e_group_join_guard() TO service_role;
CREATE TRIGGER a2e_party_member_age BEFORE INSERT OR UPDATE OF status ON public.trip_members FOR EACH ROW EXECUTE FUNCTION trip_private.a2e_group_join_guard();
CREATE OR REPLACE FUNCTION trip_private.a2e_night_theme(p_trip uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE e.culture_layer WHEN 'food' THEN ARRAY['Taste It','Make It','Guess It','Know It'] WHEN 'music' THEN ARRAY['Sing It','Move It','Guess It'] WHEN 'language' THEN ARRAY['Know It','Guess It','Tell It'] WHEN 'traditions' THEN ARRAY['Know It','Make It','Tell It','Dress It'] WHEN 'history' THEN ARRAY['Know It','Tell It','Draw It'] WHEN 'fashion' THEN ARRAY['Draw It','Make It','Dress It'] WHEN 'games' THEN ARRAY['Act It','Team Up','Vote It','Know It'] WHEN 'everyday' THEN ARRAY['Know Each Other','Tell It','Guess It','Find It'] ELSE ARRAY['Taste It','Sing It','Know It','Make It','Move It','Tell It','Draw It','Guess It'] END FROM public.culture_experiences e WHERE e.trip_id=p_trip AND e.a2e_kind IN ('show','explore') AND e.play_mode='group' AND trip_private.is_trip_member(p_trip,auth.uid()) LIMIT 1 $$;
REVOKE ALL ON FUNCTION trip_private.a2e_night_theme(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.a2e_night_theme(uuid) TO authenticated,service_role;